-- Approved workbook, not the earlier suggested pricing ratios.
-- Workbook SHA256: ed93774c63a3233a42be6c6da4ce1f546b02ab23107ab8c5722556ef1c3746a6
-- Values SHA256: 074e65b448154d3876e6245440df87972492f0f354c85c5f809b190880b55285
-- Existing receipts, entitlements, wallets and frozen Adventure plans are untouched.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
select pg_advisory_xact_lock(hashtextextended('burrow-shop-prices',0));
create temporary table pricing283_expected(id text primary key,old_price integer,old_plus boolean,old_version bigint,price integer,plus_only boolean) on commit drop;
select c.stable_id from catalog_items c join pricing283_expected e on e.id=c.stable_id order by c.stable_id for update of c;
do $guard$ begin
 if (select count(*) from pricing283_expected)<>496 or exists(
  select 1 from pricing283_expected e left join catalog_items c on c.stable_id=e.id
  where c.stable_id is null or c.status<>'active' or c.revision_id<>(select value from app_config where key='app_major_update_content_revision'))
 then raise exception 'Approved catalog identity/revision mismatch';end if;
 if not (
  not exists(select 1 from pricing283_expected e join catalog_items c on c.stable_id=e.id where (c.price,c.plus_only,c.shop_price_version) is distinct from (e.old_price,e.old_plus,e.old_version))
  or not exists(select 1 from pricing283_expected e join catalog_items c on c.stable_id=e.id where (c.price,c.plus_only,c.shop_price_version) is distinct from (e.price,e.plus_only,e.old_version+case when (e.old_price,e.old_plus) is distinct from (e.price,e.plus_only) then 1 else 0 end))
 ) then raise exception 'Concurrent pricing change: approved batch not applied';end if;
end $guard$;
select set_config('burrow.price_admin','{"batch":"ed93774c-63a3-433a-82be-6c6da4ce1f54","reason":"User-approved Burrow-Pricing-V1.xlsx SHA256 ed93774c63a3233a42be6c6da4ce1f546b02ab23107ab8c5722556ef1c3746a6"}',true);
-- WIN-01 is the expressly approved starter correction 200 -> 0. No generic
-- starter/Admin write permission or purchase/quote validation is relaxed.
update public.catalog_items c set price=e.price,plus_only=e.plus_only
 from pricing283_expected e where c.stable_id=e.id and (c.price,c.plus_only) is distinct from (e.price,e.plus_only);
create temporary table pricing283_support(product_id text primary key) on commit drop;
do $guard$ begin
 if exists(select 1 from pricing283_support e where not exists(select 1 from burrow_shop_product_identities i where i.product_id=e.product_id))
 then raise exception 'Unknown product capability';end if;
 if exists(select 1 from burrow_shop_release_support where release='d32938720e72d3b1ce81c5f667e4e81afb87a6798552183c72460b5ec3edc97c') and (
  exists(select product_id from burrow_shop_release_support where release='d32938720e72d3b1ce81c5f667e4e81afb87a6798552183c72460b5ec3edc97c' except select product_id from pricing283_support)
  or exists(select product_id from pricing283_support except select product_id from burrow_shop_release_support where release='d32938720e72d3b1ce81c5f667e4e81afb87a6798552183c72460b5ec3edc97c'))
 then raise exception 'Published client capabilities cannot change';end if;
end $guard$;
do $guard$ begin
 if exists(select 1 from pricing283_expected e join catalog_items c on c.stable_id=e.id where (c.price,c.plus_only,c.shop_price_version) is distinct from (e.price,e.plus_only,e.old_version+case when (e.old_price,e.old_plus) is distinct from (e.price,e.plus_only) then 1 else 0 end))
 then raise exception 'Price audit/version contract not applied';end if;
 if (select count(*) from burrow_shop_price_audit where batch_id='ed93774c-63a3-433a-82be-6c6da4ce1f54')<>426
 then raise exception 'Approved batch audit missing or duplicated';end if;
 if exists(select 1 from pricing283_expected e where (e.old_price,e.old_plus) is distinct from (e.price,e.plus_only) and not exists(
  select 1 from burrow_shop_price_audit a where a.batch_id='ed93774c-63a3-433a-82be-6c6da4ce1f54' and a.item_id=e.id and a.old_price=e.old_price and a.new_price=e.price
   and a.old_plus_only=e.old_plus and a.new_plus_only=e.plus_only and a.version=e.old_version+1 and a.reason='User-approved Burrow-Pricing-V1.xlsx SHA256 ed93774c63a3233a42be6c6da4ce1f546b02ab23107ab8c5722556ef1c3746a6'))
 then raise exception 'Approved audit values mismatch';end if;
end $guard$;
select set_config('burrow.price_admin','',true);
-- Do NOT republish/reroll reservations or replace any existing catalog pointer.
commit;
